      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerUpgrade: payload does not match discriminant");
    case LedgerUpgradeType::LEDGER_UPGRADE_BASE_RESERVE:
      if (const auto* p = std::get_if<3>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerUpgrade: payload does not match discriminant");
    case LedgerUpgradeType::LEDGER_UPGRADE_FLAGS:
      if (const auto* p = std::get_if<4>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerUpgrade: payload does not match discriminant");
    case LedgerUpgradeType::LEDGER_UPGRADE_CONFIG:
      if (const auto* p = std::get_if<5>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerUpgrade: payload does not match discriminant");
    case LedgerUpgradeType::LEDGER_UPGRADE_MAX_SOROBAN_TX_SET_SIZE:
      if (const auto* p = std::get_if<6>(&v.v_)) { return e.i32(static_cast<std::int32_t>(v.t_)) && Codec<std::remove_cvref_t<decltype(*p)>>::encode(*p, e); }
      return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "LedgerUpgrade: payload does not match discriminant");
