const char* enum_name(TransactionEventStage v) noexcept {
  switch (v) {
    case TransactionEventStage::TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS: return "TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS";
    case TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_TX: return "TRANSACTION_EVENT_STAGE_AFTER_TX";
    case TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS: return "TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS";
    default: return nullptr;
  }
}
bool enum_from_name(std::string_view s, TransactionEventStage& v) noexcept {
  if (s == "TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS") { v = TransactionEventStage::TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS; return true; }
  if (s == "TRANSACTION_EVENT_STAGE_AFTER_TX") { v = TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_TX; return true; }
  if (s == "TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS") { v = TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS; return true; }
  return false;
}

bool Codec<TransactionEventStage>::encode(const TransactionEventStage& v, Encoder& e) {
  switch (v) {
    case TransactionEventStage::TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS:
    case TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_TX:
    case TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS:
      break;
    default: return e.fail(stellar::v1::ErrorCode::kEncodeFailed, "unknown enum value");
  }
  return e.i32(static_cast<std::int32_t>(v));
}
bool Codec<TransactionEventStage>::decode(TransactionEventStage& v, Decoder& d) {
  std::int32_t x;
  if (!d.i32(x)) return false;
  switch (x) {
    case 0: v = TransactionEventStage::TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS; return true;
    case 1: v = TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_TX; return true;
    case 2: v = TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS; return true;
    default: return d.fail(stellar::v1::ErrorCode::kDecodeFailed, "unknown enum value");
  }
}
bool Codec<TransactionEventStage>::gen(TransactionEventStage& v, XdrRng& r, std::uint32_t) {
  switch (r.index(3)) {
    case 0: v = TransactionEventStage::TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS; return true;
    case 1: v = TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_TX; return true;
    case 2: v = TransactionEventStage::TRANSACTION_EVENT_STAGE_AFTER_ALL_TXS; return true;
  }
  v = TransactionEventStage::TRANSACTION_EVENT_STAGE_BEFORE_ALL_TXS;
  return true;
}

